// LAB: Compare split updates with atomic read-modify-write
// Keep a deterministic split-load/store counterexample, then have two real workers perform 1000 atomic fetch_add operations each.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <atomic>
#include <cassert>
#include <iostream>

int main() {
    std::atomic<int> counter{0};
    const int a = counter.load();
    const int b = counter.load();
    counter.store(a + 1);
    counter.store(b + 1);
    const int split_result = counter.load();
    counter.store(0);
    counter.fetch_add(1);
    counter.fetch_add(1);
    std::cout << split_result << ' ' << counter.load() << '\n';
    assert(split_result == 1 && counter.load() == 2);
}

#include <atomic>
#include <cassert>
#include <iostream>
#include <future>

int split_update() {
    std::atomic<int> counter{0};
    const int first = counter.load(), second = counter.load();
    counter.store(first+1); counter.store(second+1);
    return counter.load();
}
int combined_updates() {
    std::atomic<int> counter{0};
    const auto worker = [&] { for(int i=0;i<1000;++i) counter.fetch_add(1); };
    auto first = std::async(std::launch::async,worker);
    auto second = std::async(std::launch::async,worker);
    first.get(); second.get();
    return counter.load();
}

int main() {
    const int split = split_update(), combined = combined_updates();
    assert(split == 1 && combined == 2000);
    std::cout << "split=" << split << " atomic=" << combined << '\n';
}

